-- Fase 04.1 — seed do contrato da org Studio JS de staging (01a0b681-8b9b-790b-921d-4518350e534b).
-- Em bancos sem essa org (CI, dev, outras instâncias) todos os comandos afetam 0 linhas.
-- Nunca sobrescreve nada já preenchido (COALESCE / IS NULL).
-- Guardado pelo id da organização; existe outra org com nome parecido (suspensa), por isso nada é buscado por nome.

-- Papel timbrado (PNG 795x1122) embutido em bytea.
INSERT INTO contract_letterheads (organization_id, sha256, mime_type, width, height, size_bytes, original_filename, data) SELECT o.id, '244bb0c89847fce8de869fb24b6e63ae4bf33d8075ad731ddbbb4c68ded197f7', 'image/png', 795, 1122, 67845, 'papel-timbrado-studio-js.png', decode('', 'base64') FROM organizations o WHERE o.id = '01a0b681-8b9b-790b-921d-4518350e534b' ON CONFLICT ON CONSTRAINT uq_cl_org_sha DO NOTHING;

-- Dados do studio (os text_* ficam NULL = texto padrão do código).
INSERT INTO contract_settings (organization_id, studio_name, studio_cnpj, studio_address, studio_representative, studio_representative_rg, forum_city, forum_uf, letterhead_sha256) SELECT o.id, 'Studio Jéssica Seixas Beauty', '48.562.103/0001-71', 'Rua Álvares de Azevedo, 74 Centro – Osasco', 'Jéssica Seixas dos Santos Rodrigues', '48.830.035-6', 'Osasco', 'SP', '244bb0c89847fce8de869fb24b6e63ae4bf33d8075ad731ddbbb4c68ded197f7' FROM organizations o WHERE o.id = '01a0b681-8b9b-790b-921d-4518350e534b' ON CONFLICT (organization_id) DO UPDATE SET studio_name = COALESCE(contract_settings.studio_name, EXCLUDED.studio_name), studio_cnpj = COALESCE(contract_settings.studio_cnpj, EXCLUDED.studio_cnpj), studio_address = COALESCE(contract_settings.studio_address, EXCLUDED.studio_address), studio_representative = COALESCE(contract_settings.studio_representative, EXCLUDED.studio_representative), studio_representative_rg = COALESCE(contract_settings.studio_representative_rg, EXCLUDED.studio_representative_rg), forum_city = COALESCE(contract_settings.forum_city, EXCLUDED.forum_city), forum_uf = COALESCE(contract_settings.forum_uf, EXCLUDED.forum_uf), letterhead_sha256 = COALESCE(contract_settings.letterhead_sha256, EXCLUDED.letterhead_sha256);

